customCSS:
.t, .history { color: #a0a0a0; }
.join { color: #5f7d2d; }
.part, .quit { color: #a0a0a0; }
.kick, .error { color: #ab4642; }
.notice { color: #ab4642; }
.action { color: #8f5b89; }
.mode, .nick, .topic, .server { color: #397f78; }
.highlight { color: #383838; background-color: #d8d8d8; border-left: 3px solid #8f5b89; padding-left: 8px; }
.reply { color: #a0a0a0; border-left: 2px solid #397e96; padding-left: 6px; }
.oper { color: #f8f8f8; background-color: #ab4642; }
.reactions { color: #397e96; background-color: #e8e8e8; }
.card { background-color: #e8e8e8; border-color: #a0a0a0; }
.card-title { color: #397e96; }
.card-desc { color: #a0a0a0; }
.daychange { color: #a0a0a0; border-color: #e8e8e8; }
